def upgrade() -> None:
    bind = op.get_bind()
    insp = inspect(bind)
    if "ops_jobs" not in set(insp.get_table_names()):
        return
    cols = {c["name"] for c in insp.get_columns("ops_jobs")}
    if "cuft" in cols or "sqft" not in cols:
        return
    op.execute("ALTER TABLE ops_jobs RENAME COLUMN sqft TO cuft")
